-- GSM transfer system, step 24.  Run ONCE in the Supabase SQL editor (after 023),
-- then run supabase/025_base_squads.sql (generated by scripts/exportBaseSquads.ts).
--
-- What this does
--  * player_base_owner : who owns every player at the start of the game (loaded by 025)
--  * room_transfers    : ONE shared record of every deal in a shared league.
--                        It is the source of truth for "who owns this player now"
--                        and it is the Transfer Windows history.
--  * club_wallets      : the budget the server checks a deal against
--  * every way of moving a player (Buy Now, offers, counter offers, market, club deals)
--    goes through ONE locked function. Players are locked per (league, player), so two
--    buyers can never get the same player.
--  * direct writes to offers / listings / transfers are closed for shared leagues.

-- =====================================================================
-- 0. start-of-game owners
-- =====================================================================
create table if not exists public.player_base_owner (
  player_id text primary key,
  club_id text not null,
  pos text not null check (pos in ('GK', 'DF', 'MF', 'FW'))
);
alter table public.player_base_owner enable row level security;
drop policy if exists "base owner read" on public.player_base_owner;
create policy "base owner read" on public.player_base_owner for select to authenticated using (true);

-- =====================================================================
-- 1. the shared record of deals
-- =====================================================================
create table if not exists public.room_transfers (
  id uuid primary key default gen_random_uuid(),
  seq bigint generated always as identity,
  room_id uuid not null references public.rooms(id) on delete cascade,
  season text not null,
  matchday int not null default 0,
  player_id text not null,
  from_club text not null,
  to_club text not null,
  seller_id uuid references auth.users(id) on delete set null,
  buyer_id uuid references auth.users(id) on delete set null,
  fee numeric(8, 1) not null check (fee >= 0),
  kind text not null check (kind in ('listing', 'offer', 'counter', 'market', 'club_buy', 'club_sell', 'abroad', 'legacy')),
  prev_id uuid references public.room_transfers(id),
  created_at timestamptz not null default clock_timestamp()
);
-- a player can only leave a given deal once: two deals can never both follow the same one
create unique index if not exists room_transfers_chain_idx
  on public.room_transfers (room_id, player_id, (coalesce(prev_id, '00000000-0000-0000-0000-000000000000'::uuid)));
create index if not exists room_transfers_player_idx on public.room_transfers (room_id, player_id, seq desc);
create index if not exists room_transfers_room_idx on public.room_transfers (room_id, seq desc);

alter table public.room_transfers enable row level security;
drop policy if exists "room deals read" on public.room_transfers;
create policy "room deals read" on public.room_transfers for select to authenticated
  using (public.is_room_member(room_id));
-- no insert / update / delete policy: only the functions below can write

-- =====================================================================
-- 2. the budget the server checks
-- =====================================================================
create table if not exists public.club_wallets (
  user_id uuid not null references auth.users(id) on delete cascade,
  league_id text not null,
  balance numeric(10, 1) not null,
  stamp timestamptz not null default now(),
  primary key (user_id, league_id)
);
alter table public.club_wallets enable row level security;
drop policy if exists "wallet read" on public.club_wallets;
create policy "wallet read" on public.club_wallets for select to authenticated using (auth.uid() = user_id);

create or replace function public.wallet_stamp() returns timestamptz
  language sql volatile as $$ select clock_timestamp() $$;
grant execute on function public.wallet_stamp() to authenticated;

-- the app reports the spendable balance it worked out, with the stamp it took BEFORE reading
create or replace function public.report_balance(p_league text, p_balance numeric, p_stamp timestamptz)
returns void language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  insert into public.club_wallets (user_id, league_id, balance, stamp)
    values (auth.uid(), p_league, round(p_balance, 1), least(coalesce(p_stamp, now()), now()))
  on conflict (user_id, league_id) do update
    set balance = excluded.balance, stamp = excluded.stamp
    where excluded.stamp >= public.club_wallets.stamp;
end $$;
grant execute on function public.report_balance(text, numeric, timestamptz) to authenticated;

-- reported balance + every deal made since the report
create or replace function public._wallet_available(p_user uuid, p_league text) returns numeric
language sql stable security definer set search_path = public as $$
  select w.balance + coalesce((
    select sum(case when t.kind = 'sell' then t.fee else -t.fee end)
    from public.transfers t
    where t.user_id = p_user
      and (t.league_id = p_league or (t.league_id is null and position('~' in p_league) = 0))
      and t.created_at > w.stamp), 0)
  from public.club_wallets w where w.user_id = p_user and w.league_id = p_league
$$;

-- =====================================================================
-- 3. small helpers
-- =====================================================================
create or replace function public._is_human_club(p_room uuid, p_club text) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.room_members where room_id = p_room and club_id = p_club)
$$;

-- does this manager run a team of a shared league (this career)?
create or replace function public.in_room_career(p_user uuid, p_league text) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.room_members m join public.rooms r on r.id = m.room_id
    where m.user_id = p_user
      and (r.league_id = p_league or (p_league is null and position('~' in r.league_id) = 0)))
$$;
grant execute on function public.in_room_career(uuid, text) to authenticated;

-- transfer window of the buyer's own calendar: matchdays 1-10 and 20-26, and between seasons
create or replace function public._window_open(p_user uuid, p_league text, p_season text) returns boolean
language plpgsql stable security definer set search_path = public as $$
declare n int; md int;
begin
  select count(*), min(matchday) filter (where status = 'scheduled') into n, md
    from public.league_matches where user_id = p_user and league_id = p_league and season = p_season;
  if n = 0 then md := 1; end if;
  return md is null or md <= 10 or (md >= 20 and md <= 26);
end $$;

create or replace function public._signing_banned(p_user uuid, p_league text) returns boolean
language plpgsql stable security definer set search_path = public as $$
begin
  if to_regclass('public.bank_loans') is null then return false; end if;
  return exists (select 1 from public.bank_loans
    where user_id = p_user and league_id = p_league and status = 'active' and stage >= 3);
end $$;

-- how many players a club has in a shared league right now (optionally one position)
create or replace function public.room_squad_count(p_room uuid, p_club text, p_pos text default null) returns int
language sql stable security definer set search_path = public as $$
  with last as (
    select distinct on (player_id) player_id, to_club
    from public.room_transfers where room_id = p_room order by player_id, seq desc
  )
  select count(*)::int from (
    select b.player_id, b.pos from public.player_base_owner b
      where b.club_id = p_club and not exists (select 1 from last l where l.player_id = b.player_id)
    union all
    select l.player_id, b.pos from last l join public.player_base_owner b on b.player_id = l.player_id
      where l.to_club = p_club
  ) s where p_pos is null or s.pos = p_pos
$$;

-- is the player really at that club? (the shared record first, then the start-of-game owner)
create or replace function public._check_from(p_room uuid, p_player text, p_from text) returns void
language plpgsql stable security definer set search_path = public as $$
declare last_to text; base text;
begin
  select t.to_club into last_to from public.room_transfers t
    where t.room_id = p_room and t.player_id = p_player order by t.seq desc limit 1;
  if found then
    if last_to <> p_from then raise exception 'PLAYER_MOVED: he is not at % any more', p_from; end if;
    return;
  end if;
  select b.club_id into base from public.player_base_owner b where b.player_id = p_player;
  if base is null then raise exception 'UNKNOWN_PLAYER: player % is not in player_base_owner (run 025_base_squads.sql)', p_player; end if;
  if public._is_human_club(p_room, base) then
    if p_from <> base then raise exception 'PLAYER_MOVED: he is not at % any more', p_from; end if;
  elsif base = 'market' then
    if p_from <> 'market' then raise exception 'PLAYER_MOVED: he is not at % any more', p_from; end if;
  else
    -- a computer club's player: the computer clubs trade among themselves, so any computer club may be his club
    if p_from = 'market' or public._is_human_club(p_room, p_from) then
      raise exception 'PLAYER_MOVED: he is not at % any more', p_from;
    end if;
  end if;
end $$;

-- THE ONE PLACE A PLAYER CHANGES CLUB. Locks the player, checks he is where the deal says, writes the shared record,
-- and closes every other listing / offer for him.
create or replace function public._room_move(
  p_room uuid, p_player text, p_from text, p_to text, p_seller uuid, p_buyer uuid,
  p_fee numeric, p_kind text, p_season text, p_matchday int, p_keep_listing uuid, p_keep_offer uuid
) returns void language plpgsql security definer set search_path = public as $$
declare v_prev uuid;
begin
  perform pg_advisory_xact_lock(hashtext('room-player:' || p_room::text || ':' || p_player));
  perform public._check_from(p_room, p_player, p_from);
  select t.id into v_prev from public.room_transfers t
    where t.room_id = p_room and t.player_id = p_player order by t.seq desc limit 1;
  insert into public.room_transfers (room_id, season, matchday, player_id, from_club, to_club, seller_id, buyer_id, fee, kind, prev_id)
    values (p_room, p_season, coalesce(p_matchday, 0), p_player, p_from, p_to, p_seller, p_buyer, round(p_fee, 1), p_kind, v_prev);
  update public.manager_listings set status = 'withdrawn'
    where room_id = p_room and player_id = p_player and status = 'open' and id is distinct from p_keep_listing;
  update public.manager_offers set status = 'rejected', updated_at = now()
    where room_id = p_room and player_id = p_player and status in ('open', 'countered') and id is distinct from p_keep_offer;
  if p_seller is not null then
    update public.transfer_listings set status = 'sold' where user_id = p_seller and player_id = p_player and status = 'open';
  end if;
end $$;

-- the buyer: window, bank ban, budget (locked, so two deals cannot spend the same money), squad size
create or replace function public._buyer_checks(p_room uuid, p_buyer uuid, p_club text, p_league text, p_season text, p_fee numeric)
returns void language plpgsql security definer set search_path = public as $$
declare v_avail numeric;
begin
  if not public._window_open(p_buyer, p_league, p_season) then
    raise exception 'WINDOW_CLOSED: the transfer window is closed for the buyer';
  end if;
  if public._signing_banned(p_buyer, p_league) then
    raise exception 'SIGNING_BANNED: the bank has banned signings for the buyer';
  end if;
  perform pg_advisory_xact_lock(hashtext('wallet:' || p_buyer::text || ':' || p_league));
  v_avail := public._wallet_available(p_buyer, p_league);
  if v_avail is null then raise exception 'NO_WALLET: the buyer has not opened the transfer page yet, so his budget is unknown'; end if;
  if p_fee > v_avail then raise exception 'INSUFFICIENT_FUNDS: the buyer cannot afford this'; end if;
  if public.room_squad_count(p_room, p_club) > 35 then raise exception 'SQUAD_FULL: the buyer''s squad is full (35)'; end if;
end $$;

-- the seller: he must keep enough players in that position
create or replace function public._seller_checks(p_room uuid, p_club text, p_player text) returns void
language plpgsql security definer set search_path = public as $$
declare v_pos text; v_min int;
begin
  select pos into v_pos from public.player_base_owner where player_id = p_player;
  v_min := case v_pos when 'GK' then 2 when 'DF' then 5 when 'MF' then 5 else 3 end;
  if public.room_squad_count(p_room, p_club, v_pos) < v_min then
    raise exception 'SQUAD_TOO_SMALL: the seller would have too few % players', v_pos;
  end if;
end $$;

do $$
declare f record;
begin
  for f in
    select p.oid::regprocedure as sig from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.proname in
      ('_wallet_available', '_is_human_club', '_window_open', '_signing_banned', '_check_from', '_room_move', '_buyer_checks', '_seller_checks')
  loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
  end loop;
end $$;
grant execute on function public.room_squad_count(uuid, text, text) to authenticated;

-- =====================================================================
-- 4. Transfer Market: list a player, withdraw, Buy Now
-- =====================================================================
create or replace function public.list_room_player(p_room uuid, p_player text, p_asking numeric) returns uuid
language plpgsql security definer set search_path = public as $$
declare v_club text; v_id uuid;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  select club_id into v_club from public.room_members where room_id = p_room and user_id = auth.uid();
  if v_club is null then raise exception 'NOT_ALLOWED: you are not in this league'; end if;
  if p_asking is null or p_asking <= 0 or p_asking > 9999 then raise exception 'NOT_ALLOWED: bad asking price'; end if;
  perform pg_advisory_xact_lock(hashtext('room-player:' || p_room::text || ':' || p_player));
  perform public._check_from(p_room, p_player, v_club);
  insert into public.manager_listings (room_id, seller_id, seller_club, player_id, asking)
    values (p_room, auth.uid(), v_club, p_player, round(p_asking, 1)) returning id into v_id;
  return v_id;
end $$;
grant execute on function public.list_room_player(uuid, text, numeric) to authenticated;

create or replace function public.withdraw_room_listing(p_listing uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  update public.manager_listings set status = 'withdrawn'
    where id = p_listing and seller_id = auth.uid() and status = 'open';
  if not found then raise exception 'NOT_AVAILABLE: that listing is not open any more'; end if;
end $$;
grant execute on function public.withdraw_room_listing(uuid) to authenticated;

-- Buy Now: the buyer pays the asking price, the player moves, both budgets and squads follow
-- (same signature as before, so the app keeps working)
create or replace function public.buy_manager_listing(
  p_listing uuid, p_buyer_club text, p_from_club text, p_season text, p_matchday int
) returns void language plpgsql security definer set search_path = public as $$
declare l public.manager_listings; v_uid uuid := auth.uid(); v_club text; v_lg text; v_base text; v_buyer_from text;
begin
  if v_uid is null then raise exception 'not signed in'; end if;
  select * into l from public.manager_listings where id = p_listing for update;
  if l.id is null or l.status <> 'open' then raise exception 'NOT_AVAILABLE: listing is not available'; end if;
  if l.seller_id = v_uid then raise exception 'NOT_ALLOWED: you cannot buy your own player'; end if;
  select club_id into v_club from public.room_members where room_id = l.room_id and user_id = v_uid;
  if v_club is null then raise exception 'NOT_ALLOWED: not in this league'; end if;
  if v_club <> p_buyer_club then raise exception 'NOT_ALLOWED: wrong club'; end if;
  if not exists (select 1 from public.room_members where room_id = l.room_id and user_id = l.seller_id and club_id = l.seller_club) then
    raise exception 'NOT_AVAILABLE: the seller no longer manages that club';
  end if;
  select league_id into v_lg from public.rooms where id = l.room_id;

  perform public._room_move(l.room_id, l.player_id, l.seller_club, v_club, l.seller_id, v_uid, l.asking, 'listing', p_season, p_matchday, l.id, null);
  perform public._buyer_checks(l.room_id, v_uid, v_club, v_lg, p_season, l.asking);
  perform public._seller_checks(l.room_id, l.seller_club, l.player_id);

  -- the buyer's own record says where the player started in the game (the seller's club or his first club)
  select club_id into v_base from public.player_base_owner where player_id = l.player_id;
  v_buyer_from := case when p_from_club in (l.seller_club, v_base) then p_from_club else l.seller_club end;

  insert into public.transfers (user_id, season, player_id, from_club, to_club, fee, kind, matchday, league_id, created_at)
    values (v_uid, p_season, l.player_id, v_buyer_from, v_club, l.asking, 'buy', p_matchday, v_lg, clock_timestamp());
  insert into public.transfers (user_id, season, player_id, from_club, to_club, fee, kind, matchday, league_id, created_at)
    values (l.seller_id, p_season, l.player_id, l.seller_club, v_club, l.asking, 'sell', p_matchday, v_lg, clock_timestamp());
  update public.manager_listings set status = 'sold' where id = l.id;
end $$;
grant execute on function public.buy_manager_listing(uuid, text, text, text, int) to authenticated;

-- =====================================================================
-- 5. Negotiations: make an offer, answer it, accept
-- =====================================================================
create or replace function public.send_room_offer(p_room uuid, p_seller_club text, p_player text, p_amount numeric, p_season text)
returns uuid language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid(); v_club text; v_seller uuid; v_lg text; v_avail numeric; v_id uuid;
begin
  if v_uid is null then raise exception 'not signed in'; end if;
  select club_id into v_club from public.room_members where room_id = p_room and user_id = v_uid;
  if v_club is null then raise exception 'NOT_ALLOWED: you are not in this league'; end if;
  select user_id into v_seller from public.room_members where room_id = p_room and club_id = p_seller_club;
  if v_seller is null then raise exception 'NOT_ALLOWED: that club has no manager'; end if;
  if v_seller = v_uid then raise exception 'NOT_ALLOWED: you cannot make an offer to yourself'; end if;
  if p_amount is null or p_amount <= 0 or p_amount > 9999 then raise exception 'NOT_ALLOWED: bad offer'; end if;
  select league_id into v_lg from public.rooms where id = p_room;
  perform public._check_from(p_room, p_player, p_seller_club);
  if not public._window_open(v_uid, v_lg, p_season) then raise exception 'WINDOW_CLOSED: the transfer window is closed'; end if;
  if public._signing_banned(v_uid, v_lg) then raise exception 'SIGNING_BANNED: the bank has banned signings'; end if;
  v_avail := public._wallet_available(v_uid, v_lg);
  if v_avail is not null and p_amount > v_avail then raise exception 'INSUFFICIENT_FUNDS: you cannot afford this offer'; end if;
  insert into public.manager_offers (room_id, buyer_id, buyer_club, seller_id, seller_club, player_id, amount, season)
    values (p_room, v_uid, v_club, v_seller, p_seller_club, p_player, round(p_amount, 1), p_season) returning id into v_id;
  return v_id;
end $$;
grant execute on function public.send_room_offer(uuid, text, text, numeric, text) to authenticated;

-- action: reject (seller), counter (seller, needs a price), withdraw (buyer)
create or replace function public.answer_room_offer(p_offer uuid, p_action text, p_counter numeric default null)
returns void language plpgsql security definer set search_path = public as $$
declare o public.manager_offers; v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'not signed in'; end if;
  select * into o from public.manager_offers where id = p_offer for update;
  if o.id is null then raise exception 'NOT_AVAILABLE: offer not found'; end if;
  if p_action = 'reject' then
    if o.seller_id <> v_uid or o.status <> 'open' then raise exception 'NOT_ALLOWED: you cannot refuse this offer'; end if;
    update public.manager_offers set status = 'rejected', updated_at = now() where id = o.id;
  elsif p_action = 'counter' then
    if o.seller_id <> v_uid or o.status <> 'open' then raise exception 'NOT_ALLOWED: you cannot answer this offer'; end if;
    if p_counter is null or p_counter <= 0 or p_counter > 9999 then raise exception 'NOT_ALLOWED: bad price'; end if;
    perform public._check_from(o.room_id, o.player_id, o.seller_club);
    update public.manager_offers set status = 'countered', counter = round(p_counter, 1), updated_at = now() where id = o.id;
  elsif p_action = 'withdraw' then
    if o.buyer_id <> v_uid or o.status not in ('open', 'countered') then raise exception 'NOT_ALLOWED: you cannot withdraw this offer'; end if;
    update public.manager_offers set status = 'withdrawn', updated_at = now() where id = o.id;
  else
    raise exception 'NOT_ALLOWED: unknown action';
  end if;
end $$;
grant execute on function public.answer_room_offer(uuid, text, numeric) to authenticated;

-- the seller accepts an open offer, or the buyer accepts the counter price (same signature as before)
create or replace function public.accept_manager_offer(p_offer uuid, p_season text, p_matchday int)
returns void language plpgsql security definer set search_path = public as $$
declare o public.manager_offers; v_price numeric(8, 1); v_lg text; v_kind text; v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'not signed in'; end if;
  select * into o from public.manager_offers where id = p_offer for update;
  if o.id is null then raise exception 'NOT_AVAILABLE: offer not found'; end if;
  select league_id into v_lg from public.rooms where id = o.room_id;
  if o.status = 'open' then
    if o.seller_id <> v_uid then raise exception 'NOT_ALLOWED: only the seller can accept this offer'; end if;
    v_price := o.amount; v_kind := 'offer';
  elsif o.status = 'countered' then
    if o.buyer_id <> v_uid then raise exception 'NOT_ALLOWED: only the buyer can accept the counter price'; end if;
    v_price := o.counter; v_kind := 'counter';
  else
    raise exception 'NOT_AVAILABLE: this offer is closed';
  end if;
  if not exists (select 1 from public.room_members where room_id = o.room_id and user_id = o.seller_id and club_id = o.seller_club)
     or not exists (select 1 from public.room_members where room_id = o.room_id and user_id = o.buyer_id and club_id = o.buyer_club) then
    raise exception 'NOT_AVAILABLE: a club of this deal changed manager';
  end if;

  perform public._room_move(o.room_id, o.player_id, o.seller_club, o.buyer_club, o.seller_id, o.buyer_id, v_price, v_kind, p_season, p_matchday, null, o.id);
  perform public._buyer_checks(o.room_id, o.buyer_id, o.buyer_club, v_lg, p_season, v_price);
  perform public._seller_checks(o.room_id, o.seller_club, o.player_id);

  insert into public.transfers (user_id, season, player_id, from_club, to_club, fee, kind, matchday, league_id, created_at)
    values (o.buyer_id, p_season, o.player_id, o.seller_club, o.buyer_club, v_price, 'buy', p_matchday, v_lg, clock_timestamp());
  insert into public.transfers (user_id, season, player_id, from_club, to_club, fee, kind, matchday, league_id, created_at)
    values (o.seller_id, p_season, o.player_id, o.seller_club, o.buyer_club, v_price, 'sell', p_matchday, v_lg, clock_timestamp());
  update public.manager_offers set status = 'accepted', updated_at = now() where id = o.id;
end $$;
grant execute on function public.accept_manager_offer(uuid, text, int) to authenticated;

-- =====================================================================
-- 6. every other deal of the app: world market, computer clubs, abroad
-- =====================================================================
-- Playing alone it simply saves the deal. In a shared league it claims the player in the shared record.
create or replace function public.room_record_deal(
  p_season text, p_player text, p_from text, p_to text, p_fee numeric, p_kind text, p_matchday int, p_league text
) returns text language plpgsql security definer set search_path = public as $$
declare v_uid uuid := auth.uid(); v_room uuid; v_club text; v_lg text;
begin
  if v_uid is null then raise exception 'not signed in'; end if;
  if p_fee is null or p_fee < 0 or p_kind not in ('buy', 'sell') then raise exception 'NOT_ALLOWED: bad deal'; end if;
  select r.id, m.club_id, r.league_id into v_room, v_club, v_lg
    from public.rooms r join public.room_members m on m.room_id = r.id
    where m.user_id = v_uid and (r.league_id = p_league or (p_league is null and position('~' in r.league_id) = 0))
    limit 1;
  if v_room is null then
    insert into public.transfers (user_id, season, player_id, from_club, to_club, fee, kind, matchday, league_id)
      values (v_uid, p_season, p_player, p_from, p_to, p_fee, p_kind, coalesce(p_matchday, 0), p_league);
    return 'solo';
  end if;

  if p_kind = 'buy' then
    if p_to <> v_club then raise exception 'NOT_ALLOWED: you can only sign players for your own club'; end if;
    if public._is_human_club(v_room, p_from) then raise exception 'NOT_ALLOWED: a player of another manager is bought through an offer'; end if;
    perform public._room_move(v_room, p_player, p_from, v_club, null, v_uid, p_fee,
      case when p_from = 'market' then 'market' else 'club_buy' end, p_season, p_matchday, null, null);
    perform public._buyer_checks(v_room, v_uid, v_club, v_lg, p_season, p_fee);
  else
    if p_from <> v_club then raise exception 'NOT_ALLOWED: you can only sell your own players'; end if;
    if public._is_human_club(v_room, p_to) then raise exception 'NOT_ALLOWED: sell to another manager through a listing'; end if;
    perform public._room_move(v_room, p_player, v_club, p_to, v_uid, null, p_fee,
      case when p_to = 'abroad' then 'abroad' else 'club_sell' end, p_season, p_matchday, null, null);
    if p_to <> 'abroad' then perform public._seller_checks(v_room, v_club, p_player); end if;
  end if;

  insert into public.transfers (user_id, season, player_id, from_club, to_club, fee, kind, matchday, league_id, created_at)
    values (v_uid, p_season, p_player, p_from, p_to, p_fee, p_kind, coalesce(p_matchday, 0), v_lg, clock_timestamp());
  return 'room';
end $$;
grant execute on function public.room_record_deal(text, text, text, text, numeric, text, int, text) to authenticated;

-- =====================================================================
-- 7. close the direct doors (shared leagues only; playing alone still works as before)
-- =====================================================================
drop policy if exists "offers add" on public.manager_offers;
drop policy if exists "offers edit" on public.manager_offers;
drop policy if exists "mlist add" on public.manager_listings;
drop policy if exists "mlist edit" on public.manager_listings;

drop policy if exists "Managers add own transfers" on public.transfers;
create policy "Managers add own transfers" on public.transfers
  for insert to authenticated
  with check (auth.uid() = user_id and not public.in_room_career(auth.uid(), league_id));

-- =====================================================================
-- 8. deals that happened before this step: copy them into the shared record (once)
-- =====================================================================
insert into public.room_transfers (id, room_id, season, matchday, player_id, from_club, to_club, fee, kind, prev_id, created_at)
select c.nid, c.room_id, c.season, c.matchday, c.player_id, c.from_club, c.to_club, c.fee, 'legacy',
       lag(c.nid) over (partition by c.room_id, c.player_id order by c.created_at, c.nid),
       c.created_at
from (
  select d.*, gen_random_uuid() as nid from (
    select distinct on (r.id, t.player_id, t.to_club, t.season, t.matchday, t.created_at)
      r.id as room_id, t.season, t.matchday, t.player_id, t.from_club, t.to_club, t.fee, t.created_at
    from public.rooms r
    join public.room_members m on m.room_id = r.id
    join public.transfers t on t.user_id = m.user_id
    where t.league_id = r.league_id or (t.league_id is null and position('~' in r.league_id) = 0)
    order by r.id, t.player_id, t.to_club, t.season, t.matchday, t.created_at, (t.kind = 'sell') desc
  ) d
) c
where not exists (select 1 from public.room_transfers)
order by c.created_at, c.nid;

-- =====================================================================
-- 9. live updates
-- =====================================================================
do $$
begin
  begin alter publication supabase_realtime add table public.manager_offers; exception when duplicate_object then null; when undefined_object then null; end;
  begin alter publication supabase_realtime add table public.manager_listings; exception when duplicate_object then null; when undefined_object then null; end;
  begin alter publication supabase_realtime add table public.room_transfers; exception when duplicate_object then null; when undefined_object then null; end;
end $$;
